<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background-color: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 24px;
  }

  h1 {
    font-size: 1.5rem;
    margin-bottom: 8px;
    color: #c7d2fe;
  }

  #controls {
    display: flex;
    gap: 10px;
    margin-bottom: 16px;
  }

  button {
    padding: 8px 20px;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
  }

  button:hover { transform: translateY(-1px); filter: brightness(1.15); }
  button:active { transform: translateY(0); }

  #sort { background-color: #6366f1; color: #fff; }
  #shuffle { background-color: #ec4899; color: #fff; }
  #reset { background-color: #374151; color: #d1d5db; }

  #status {
    height: 20px;
    margin-bottom: 12px;
    font-size: 0.9rem;
    color: #a5b4fc;
  }

  #bars {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    height: 300px;
    width: 100%;
    max-width: 800px;
    border-bottom: 2px solid #374151;
  }

  .bar {
    flex: 1;
    min-width: 6px;
    background-color: #6366f1;
    border-radius: 3px 3px 0 0;
    transition: height 0.2s ease, background-color 0.2s ease;
    position: relative;
  }

  .bar.compare { background-color: #f59e0b; }
  .bar.swap { background-color: #ec4899; }
</style>
</head>
<body>

<h1>Sorting Visualizer</h1>
<div id="controls">
  <button id="sort">Sort</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div id="status"></div>
<div id="bars"></div>

<script>
(function () {
  const ARRAY_SIZE = 30;
  const MAX_VAL = 100;
  let array = [];
  let barsContainer = document.getElementById('bars');
  let statusEl = document.getElementById('status');
  let sortStepIntervalId = null;

  // --- Rendering ---

  function renderBars(arr) {
    barsContainer.innerHTML = '';
    const maxVal = Math.max(...arr);
    arr.forEach((val, i) => {
      const bar = document.createElement('div');
      bar.className = 'bar';
      const heightPct = (val / maxVal) * 100;
      bar.style.height = Math.round(heightPct) + '%';
      bar.dataset.index = i;
      barsContainer.appendChild(bar);
    });
  }

  function highlightCompare(i, j) {
    if (i !== -1 && i < array.length) {
      const b = barsContainer.children[i];
      b.classList.add('compare');
    }
    if (j !== -1 && j < array.length) {
      const b = barsContainer.children[j];
      b.classList.add('compare');
    }
  }

  function highlightSwap(i, j) {
    if (i !== -1) {
      const b = barsContainer.children[i];
      b.classList.remove('compare');
      b.classList.add('swap');
    }
    if (j !== -1) {
      const b = barsContainer.children[j];
      b.classList.remove('compare');
      b.classList.add('swap');
    }
  }

  function clearHighlights() {
    Array.from(barsContainer.children).forEach(b => {
      b.classList.remove('compare', 'swap');
    });
  }

  // --- API ---

  window.viz = {
    array: function () { return [...array]; },
    setArray: function (a) {
      array = a.slice();
      renderBars(array);
    },
    sortStep: function () {
      if (!isSorted()) return false;
      // Bubble sort one comparison-exchange step
      let i = 0;
      while (i < array.length - 1) {
        clearHighlights();
        highlightCompare(i, i + 1);
        setTimeout(() => {
          if (array[i] > array[i + 1]) {
            // Swap
            const tmp = array[i];
            array[i] = array[i + 1];
            array[i + 1] = tmp;
            highlightSwap(i, i + 1);
          }
          clearHighlights();
          if (isSorted()) return true;
        }, 40);
        i++;
      }
      // If we get here without returning above, the loop finished all comparisons
      // but they were already in order — so it's sorted.
      return true;
    },
    sorted: function () {
      for (let i = 0; i < array.length - 1; i++) {
        if (array[i] > array[i + 1]) return false;
      }
      return true;
    }
  };

  // --- Helpers ---

  function isSorted() { return viz.sorted(); }

  function shuffleArray(a) {
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
  }

  function generateArray() {
    return Array.from({ length: ARRAY_SIZE }, () =>
      Math.floor(Math.random() * MAX_VAL) + 1
    );
  }

  // --- Event Handlers ---

  document.getElementById('sort').addEventListener('click', function () {
    clearInterval(sortStepIntervalId);
    statusEl.textContent = 'Sorting...';
    sortStepIntervalId = setInterval(function () {
      if (viz.sortStep()) {
        clearInterval(sortStepIntervalId);
        statusEl.textContent = isSorted() ? '✅ Array sorted!' : '';
      } else {
        statusEl.textContent = '';
      }
    }, 40);
  });

  document.getElementById('shuffle').addEventListener('click', function () {
    const arr = generateArray();
    shuffleArray(arr);
    viz.setArray(arr);
    statusEl.textContent = 'Shuffled.';
  });

  document.getElementById('reset').addEventListener('click', function () {
    clearInterval(sortStepIntervalId);
    array = [];
    renderBars([]);
    statusEl.textContent = '';
  });

  // --- Init ---

  let initArray = generateArray();
  shuffleArray(initArray);
  viz.setArray(initArray);
})();
</script>
</body>
</html>
